CREATE DATABASE IF NOT EXISTS sasa_resort CHARACTER SET utf8mb4;
USE sasa_resort;
CREATE TABLE cottages(id INT AUTO_INCREMENT PRIMARY KEY,cottage_no INT UNIQUE,name VARCHAR(80),capacity INT DEFAULT 15,price DECIMAL(8,2) DEFAULT 300,status ENUM('available','maintenance') DEFAULT 'available',description VARCHAR(255),amenities VARCHAR(255),image VARCHAR(100));
CREATE TABLE reservations(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),contact_number VARCHAR(30),reservation_date DATE,guests INT,type ENUM('day','overnight'),arrival_time TIME,special_request TEXT,total_amount DECIMAL(8,2),down_payment DECIMAL(8,2),status ENUM('pending','approved','rejected','cancelled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,token CHAR(32),payment_method ENUM('ewallet','resort') DEFAULT 'resort',payment_ref VARCHAR(60),payment_proof VARCHAR(100),payment_status ENUM('unpaid','submitted','verified','rejected') DEFAULT 'unpaid',paid_at DATETIME NULL);
CREATE TABLE reservation_cottages(reservation_id INT,cottage_id INT,PRIMARY KEY(reservation_id,cottage_id),FOREIGN KEY(reservation_id) REFERENCES reservations(id) ON DELETE CASCADE,FOREIGN KEY(cottage_id) REFERENCES cottages(id));
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE,password_hash VARCHAR(255));
CREATE TABLE settings(k VARCHAR(50) PRIMARY KEY,v VARCHAR(255));
